<template>
    <component v-if="!asChild" :is="as" :class="cx('root')" @click="onClick" v-bind="attrs">
        <slot />
    </component>
    <slot v-else :a11yAttrs="a11yAttrs" :class="cx('root')" :onClick="onClick" />
</template>

<script>
import { mergeProps } from 'vue';
import BaseSidebarMain from './BaseSidebarMain.vue';

export default {
    name: 'SidebarMain',
    extends: BaseSidebarMain,
    inheritAttrs: false,
    inject: {
        $pcSidebarLayout: { default: null }
    },
    methods: {
        onClick(event) {
            this.$pcSidebarLayout?.onMainClick(event);
        }
    },
    computed: {
        a11yAttrs() {
            return {
                'data-pc-name': 'sidebarmain',
                'data-pc-section': 'root'
            };
        },
        attrs() {
            return mergeProps(this.a11yAttrs, this.ptmi('root'));
        }
    }
};
</script>
